import{_ as n,c as a,b as e,o as t}from"./app-90veb4I1.js";const p={};function o(l,s){return t(),a("div",null,s[0]||(s[0]=[e(`<h1 id="shape" tabindex="-1"><a class="header-anchor" href="#shape"><span>Shape</span></a></h1><p>The shape of an Openmadness array describes its dimensions or structure. Think of it as how your data is organized – like the rows and columns of a spreadsheet.</p><ul><li>A simple list of numbers has one dimension.</li><li>A table of numbers has two dimensions (rows and columns). The shape property returns an array indicating the size of each dimension.</li></ul><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code><span class="line"><span class="token keyword">import</span> om <span class="token keyword">from</span> <span class="token string">&#39;openmadness&#39;</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token comment">// A 1-dimensional array (like a single list)</span></span>
<span class="line"><span class="token keyword">const</span> dailyVisitors <span class="token operator">=</span> om<span class="token punctuation">.</span><span class="token function">array</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token number">1000</span><span class="token punctuation">,</span> <span class="token number">1200</span><span class="token punctuation">,</span> <span class="token number">950</span><span class="token punctuation">,</span> <span class="token number">1300</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span><span class="token string">&quot;Daily Visitors data:&quot;</span><span class="token punctuation">,</span> dailyVisitors<span class="token punctuation">.</span>data<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span><span class="token string">&quot;Shape of Daily Visitors:&quot;</span><span class="token punctuation">,</span> dailyVisitors<span class="token punctuation">.</span>shape<span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// Output: [4]</span></span>
<span class="line"><span class="token comment">// It has 4 elements in its single dimension.</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// A 2-dimensional array (like a grid or table)</span></span>
<span class="line"><span class="token keyword">const</span> quarterlySales <span class="token operator">=</span> om<span class="token punctuation">.</span><span class="token function">array</span><span class="token punctuation">(</span><span class="token punctuation">[</span></span>
<span class="line">    <span class="token punctuation">[</span><span class="token number">100</span><span class="token punctuation">,</span> <span class="token number">120</span><span class="token punctuation">,</span> <span class="token number">90</span><span class="token punctuation">]</span><span class="token punctuation">,</span>  <span class="token comment">// Q1 sales for 3 regions</span></span>
<span class="line">    <span class="token punctuation">[</span><span class="token number">110</span><span class="token punctuation">,</span> <span class="token number">130</span><span class="token punctuation">,</span> <span class="token number">95</span><span class="token punctuation">]</span><span class="token punctuation">,</span>  <span class="token comment">// Q2 sales for 3 regions</span></span>
<span class="line">    <span class="token punctuation">[</span><span class="token number">105</span><span class="token punctuation">,</span> <span class="token number">125</span><span class="token punctuation">,</span> <span class="token number">100</span><span class="token punctuation">]</span>  <span class="token comment">// Q3 sales for 3 regions</span></span>
<span class="line"><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span><span class="token string">&quot;\\nQuarterly Sales data:\\n&quot;</span><span class="token punctuation">,</span> quarterlySales<span class="token punctuation">.</span>data<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span><span class="token string">&quot;Shape of Quarterly Sales:&quot;</span><span class="token punctuation">,</span> quarterlySales<span class="token punctuation">.</span>shape<span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// Output: [3, 3]</span></span>
<span class="line"><span class="token comment">// This means 3 rows and 3 columns.</span></span>
<span class="line"></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Understanding shape is crucial because many operations require arrays to have compatible shapes.</p>`,5)]))}const c=n(p,[["render",o]]),u=JSON.parse('{"path":"/tutorials/fundamentals/shapes.html","title":"Shapes","lang":"en-US","frontmatter":{"title":"Shapes","description":"This page will guide you on how to install openmadness"},"headers":[],"git":{"updatedTime":1751456764000,"contributors":[{"name":"Dev-Liz","username":"Dev-Liz","email":"basseyelizabeth569@gmail.com","commits":1,"url":"https://github.com/Dev-Liz"}],"changelog":[{"hash":"a6376b6867019658f19d5f27afd0cae5c3b98baa","time":1751456764000,"email":"basseyelizabeth569@gmail.com","author":"Dev-Liz","message":"updated docs"}]},"filePathRelative":"tutorials/fundamentals/shapes.md"}');export{c as comp,u as data};
